// ---------------------------------------------------------------------------
// Harness
// ---------------------------------------------------------------------------

type fakeCall struct {
	path   string
	params map[string]string
}

// fakeGarmin answers requests from a path-prefix routing table and records
// every call in order.
type fakeGarmin struct {
	calls   []fakeCall
	respond func(call fakeCall, n int) (json.RawMessage, error)
}

func (f *fakeGarmin) Get(_ context.Context, path string, params map[string]string) (json.RawMessage, error) {
	copied := map[string]string{}
	for k, v := range params {
		copied[k] = v
	}
	call := fakeCall{path: path, params: copied}
	f.calls = append(f.calls, call)
	return f.respond(call, len(f.calls))
}

func (f *fakeGarmin) pathsMatching(substr string) []fakeCall {
	var out []fakeCall
	for _, c := range f.calls {
		if strings.Contains(c.path, substr) {
			out = append(out, c)
		}
	}
	return out
}

func testStore(t *testing.T) *store.Store {
	t.Helper()
	db, err := store.Open(filepath.Join(t.TempDir(), "data.db"))
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	if err := db.EnsureGarminSeriesState(); err != nil {
		t.Fatalf("ensure series state: %v", err)
	}
	return db
}

func fixedClock(day string) func() time.Time {
	d := mustParseCivilDay(day)
	return func() time.Time { return time.Date(d.year, d.month, d.day, 12, 0, 0, 0, time.UTC) }
}

type sleepRecorder struct {
	total time.Duration
	n     int
}

func (s *sleepRecorder) sleep(d time.Duration) { s.total += d; s.n++ }

func newTestWalker(t *testing.T, db *store.Store, api *fakeGarmin, opts garminWalkOptions) (*garminWalker, *sleepRecorder) {
	t.Helper()
	if opts.now == nil {
		opts.now = fixedClock("2026-09-08")
	}
	if opts.loc == nil {
		opts.loc = time.UTC
	}
	if opts.days == 0 {
		opts.days = 28
	}
	if opts.emptyWindowCeiling == 0 {
		opts.emptyWindowCeiling = 13
	}
	if opts.activityPageSize == 0 {
		opts.activityPageSize = 100
	}
	rec := &sleepRecorder{}
	return &garminWalker{
		client: api,
		db:     db,
		emit:   &garminEmitter{w: io.Discard, machine: true},
		opts:   opts,
		pacer:  newGarminPacer(opts.delay, rec.sleep),
	}, rec
}

func seriesNamed(t *testing.T, name string) garminSeries {
	t.Helper()
	s, ok := garminSeriesByName()[name]
	if !ok {
		t.Fatalf("series %q is not in the catalog", name)
	}
	return s
}

// stepsWindowPayload builds a steps response covering every day in the range.
func stepsWindowPayload(path string) json.RawMessage {
	// path is /usersummary-service/stats/steps/daily/<start>/<end>
	parts := strings.Split(strings.TrimPrefix(path, "/usersummary-service/stats/steps/daily/"), "/")
	start := mustParseCivilDay(parts[0])
	end := mustParseCivilDay(parts[1])
	var rows []string
	for d := start; !d.after(end); d = d.addDays(1) {
		rows = append(rows, fmt.Sprintf(`{"calendarDate":%q,"totalSteps":1000,"stepGoal":7500}`, d.String()))
	}
	return json.RawMessage("[" + strings.Join(rows, ",") + "]")
}

// ---------------------------------------------------------------------------
// Forward walk and bookmark semantics
// ---------------------------------------------------------------------------

func TestWalkWindowed_StoresEveryDayAndNeverBookmarksToday(t *testing.T) {
	db := testStore(t)
	api := &fakeGarmin{respond: func(c fakeCall, _ int) (json.RawMessage, error) {
		return stepsWindowPayload(c.path), nil
	}}
	w, _ := newTestWalker(t, db, api, garminWalkOptions{days: 56, now: fixedClock("2026-09-08")})

	out := w.walkSeries(context.Background(), seriesNamed(t, "steps"))
	if out.errored {
		t.Fatalf("walk errored: %v", out.err)
	}
	if out.stored != 56 {
		t.Fatalf("stored %d rows, want 56 (one per day of the requested range)", out.stored)
	}
	if len(api.calls) != 2 {
		t.Fatalf("made %d calls, want 2 (56 days at a 28-day cap)", len(api.calls))
	}

	st, err := db.GetGarminSeriesState("steps")
	if err != nil {
		t.Fatalf("state: %v", err)
	}
	if st.LastCompleteDay != "2026-09-07" {
		t.Fatalf("last_complete_day = %q, want 2026-09-07: today is still accruing and must never be bookmarked complete", st.LastCompleteDay)
	}
	if st.EarliestDay != "2026-07-15" {
		t.Fatalf("earliest_day = %q, want 2026-07-15", st.EarliestDay)
	}
	if st.TotalRows != 56 {
		t.Fatalf("total_rows = %d, want 56", st.TotalRows)
	}
	// Today's partial row is still stored, it is only not bookmarked.
	if _, err := db.Get("steps", "2026-09-08"); err != nil {
		t.Fatalf("today's partial row was not stored: %v", err)
	}

	// The generated sync_state row is mirrored so generated readers see it.
	cursor, _, count, err := db.GetSyncState("steps")
	if err != nil {
		t.Fatalf("GetSyncState: %v", err)
	}
	if cursor != "2026-09-07" || count != 56 {
		t.Fatalf("mirrored sync_state = (%q, %d), want (2026-09-07, 56)", cursor, count)
	}
}

func TestWalkWindowed_SecondRunResumesFromTheBookmark(t *testing.T) {
	db := testStore(t)
	api := &fakeGarmin{respond: func(c fakeCall, _ int) (json.RawMessage, error) {
		return stepsWindowPayload(c.path), nil
	}}
	first, _ := newTestWalker(t, db, api, garminWalkOptions{days: 56, now: fixedClock("2026-09-08")})
	first.walkSeries(context.Background(), seriesNamed(t, "steps"))
	callsAfterFirst := len(api.calls)

	// Three days later the archive only owes those three days plus today.
	second, _ := newTestWalker(t, db, api, garminWalkOptions{days: 56, now: fixedClock("2026-09-11")})
	out := second.walkSeries(context.Background(), seriesNamed(t, "steps"))
	if out.errored {
		t.Fatalf("second walk errored: %v", out.err)
	}
	newCalls := len(api.calls) - callsAfterFirst
	if newCalls != 1 {
		t.Fatalf("the incremental run made %d calls, want 1: it must ask only for 2026-09-08..2026-09-11", newCalls)
	}
	got := api.calls[len(api.calls)-1].path
	if !strings.HasSuffix(got, "/2026-09-08/2026-09-11") {
		t.Fatalf("incremental window = %s, want 2026-09-08..2026-09-11", got)
	}
	st, _ := db.GetGarminSeriesState("steps")
	if st.LastCompleteDay != "2026-09-10" {
		t.Fatalf("last_complete_day after the second run = %q, want 2026-09-10", st.LastCompleteDay)
	}
}

// A run that dies mid-walk must leave a bookmark that the next run resumes
// from, rather than losing every window it already paid for.
func TestWalkWindowed_CheckpointsEachWindowSoAFailureResumes(t *testing.T) {
	db := testStore(t)
	boom := errors.New("connection reset by peer")
	failFrom := 3
	api := &fakeGarmin{respond: func(c fakeCall, n int) (json.RawMessage, error) {
		if n >= failFrom {
			return nil, boom
		}
		return stepsWindowPayload(c.path), nil
	}}
	// 84 days = three 28-day windows; the third fails.
	w, _ := newTestWalker(t, db, api, garminWalkOptions{days: 84, now: fixedClock("2026-09-08")})
	out := w.walkSeries(context.Background(), seriesNamed(t, "steps"))
	if out.errored {
		t.Fatalf("a transport failure on one window must warn, not fail the series: %v", out.err)
	}
	if !out.warned {
		t.Fatal("a failed window did not warn")
	}
	if out.stored != 56 {
		t.Fatalf("stored %d rows before the failure, want 56 from the first two windows", out.stored)
	}
	st, _ := db.GetGarminSeriesState("steps")
	if st.LastCompleteDay != "2026-08-11" {
		t.Fatalf("last_complete_day = %q; the bookmark must record the last window that actually landed (2026-08-11), so a resume asks only for what is missing", st.LastCompleteDay)
	}

	// Resume: the API recovers, and only the missing tail is re-requested.
	callsBefore := len(api.calls)
	api.respond = func(c fakeCall, _ int) (json.RawMessage, error) { return stepsWindowPayload(c.path), nil }
	resume, _ := newTestWalker(t, db, api, garminWalkOptions{days: 84, now: fixedClock("2026-09-08")})
	out2 := resume.walkSeries(context.Background(), seriesNamed(t, "steps"))
	if out2.errored || out2.warned {
		t.Fatalf("resume did not run clean: warned=%v err=%v", out2.warned, out2.err)
	}
	if got := len(api.calls) - callsBefore; got != 1 {
		t.Fatalf("resume made %d calls, want 1: it must not re-walk the windows already stored", got)
	}
	if got := api.calls[len(api.calls)-1].path; !strings.HasSuffix(got, "/2026-08-12/2026-09-08") {
		t.Fatalf("resume window = %s, want 2026-08-12..2026-09-08", got)
	}
}

// ---------------------------------------------------------------------------
// Backfill and the empty-window ceiling
// ---------------------------------------------------------------------------

func TestWalkWindowed_BackfillStopsAtTheEmptyWindowCeiling(t *testing.T) {
	db := testStore(t)
	// History exists back to 2026-06-01 and nothing before it.
	historyStart := mustParseCivilDay("2026-06-01")
	api := &fakeGarmin{respond: func(c fakeCall, _ int) (json.RawMessage, error) {
		full := stepsWindowPayload(c.path)
		var rows []json.RawMessage
		_ = json.Unmarshal(full, &rows)
		kept := make([]json.RawMessage, 0, len(rows))
		for _, r := range rows {
			day, _ := dayFromValue(jsonStringField(r, "calendarDate"))
			if !day.before(historyStart) {
				kept = append(kept, r)
			}
		}
		out, _ := json.Marshal(kept)
		return out, nil
	}}
	w, _ := newTestWalker(t, db, api, garminWalkOptions{
		days: 28, backfill: true, emptyWindowCeiling: 3, now: fixedClock("2026-09-08"),
	})
	out := w.walkSeries(context.Background(), seriesNamed(t, "steps"))
	if out.errored {
		t.Fatalf("backfill errored: %v", out.err)
	}
	st, _ := db.GetGarminSeriesState("steps")
	if st.StopReason != "empty_window_ceiling" {
		t.Fatalf("stop_reason = %q, want empty_window_ceiling", st.StopReason)
	}
	if st.EmptyWindows != 3 {
		t.Fatalf("empty_windows = %d, want exactly the ceiling of 3", st.EmptyWindows)
	}
	if st.EarliestDay != "2026-06-01" {
		t.Fatalf("earliest_day = %q, want 2026-06-01 (the oldest day that actually carried data)", st.EarliestDay)
	}
	// The frontier records how deep the walk probed, which is three empty
	// windows past the oldest data.
	frontier := mustParseCivilDay(st.FrontierDay)
	if !frontier.before(mustParseCivilDay("2026-06-01")) {
		t.Fatalf("frontier_day = %q; it must sit below earliest_day so a deeper re-run does not re-probe", st.FrontierDay)
	}

	// A re-run with the same ceiling must not walk further: the walk is
	// already at its stop.
	callsBefore := len(api.calls)
	again, _ := newTestWalker(t, db, api, garminWalkOptions{
		days: 28, backfill: true, emptyWindowCeiling: 3, now: fixedClock("2026-09-08"),
	})
	again.walkSeries(context.Background(), seriesNamed(t, "steps"))
	backwardCalls := 0
	for _, c := range api.calls[callsBefore:] {
		start := strings.Split(strings.TrimPrefix(c.path, "/usersummary-service/stats/steps/daily/"), "/")[0]
		if mustParseCivilDay(start).before(mustParseCivilDay("2026-08-12")) {
			backwardCalls++
		}
	}
	if backwardCalls != 0 {
		t.Fatalf("a re-run at the same ceiling walked %d more windows backwards; the ceiling must hold", backwardCalls)
	}
}

// An empty window from a series that has never returned a single row cannot
// distinguish "this account has no data" from "this tool is asking wrong", so
// the walk must refuse to stamp an earliest_day off the back of it.
func TestWalkWindowed_NeverReturnedDataDoesNotStampEarliestDay(t *testing.T) {
	db := testStore(t)
	api := &fakeGarmin{respond: func(fakeCall, int) (json.RawMessage, error) {
		return json.RawMessage(`[]`), nil
	}}
	w, _ := newTestWalker(t, db, api, garminWalkOptions{
		days: 28, backfill: true, emptyWindowCeiling: 2, now: fixedClock("2026-09-08"),
	})
	out := w.walkSeries(context.Background(), seriesNamed(t, "steps"))
	if !out.warned {
		t.Fatal("a series that never returned a row must warn")
	}
	st, _ := db.GetGarminSeriesState("steps")
	if st.StopReason != "never_returned_data" {
		t.Fatalf("stop_reason = %q, want never_returned_data", st.StopReason)
	}
	if st.EarliestDay != "" {
		t.Fatalf("earliest_day = %q, want it left unset: an all-empty walk proves nothing about where history begins", st.EarliestDay)
	}
}

func TestWalkWindowed_BackfillStopsAtTheHistoryFloor(t *testing.T) {
	db := testStore(t)
	// Every window carries data, so only the floor can stop the walk.
	api := &fakeGarmin{respond: func(c fakeCall, _ int) (json.RawMessage, error) {
		return stepsWindowPayload(c.path), nil
	}}
	s := seriesNamed(t, "steps")
	s.floor = mustParseCivilDay("2026-01-01")
	w, _ := newTestWalker(t, db, api, garminWalkOptions{
		days: 28, backfill: true, emptyWindowCeiling: 13, now: fixedClock("2026-09-08"),
	})
	out := w.walkWindowed(context.Background(), s)
	if out.errored {
		t.Fatalf("floor walk errored: %v", out.err)
	}
	st, _ := db.GetGarminSeriesState("steps")
	if st.StopReason != "floor" {
		t.Fatalf("stop_reason = %q, want floor", st.StopReason)
	}
	if st.EarliestDay != "2026-01-01" {
		t.Fatalf("earliest_day = %q, want the floor 2026-01-01", st.EarliestDay)
	}
	for _, c := range api.calls {
		start := strings.Split(strings.TrimPrefix(c.path, "/usersummary-service/stats/steps/daily/"), "/")[0]
		if mustParseCivilDay(start).before(s.floor) {
			t.Fatalf("a window started at %s, below the floor %s", start, s.floor)
		}
	}
}

// ---------------------------------------------------------------------------
// Rate limiting
// ---------------------------------------------------------------------------

func TestWalk_FailsFastOnRateLimitWithoutRetrying(t *testing.T) {
	db := testStore(t)
	api := &fakeGarmin{respond: func(c fakeCall, n int) (json.RawMessage, error) {
		if n == 1 {
			return stepsWindowPayload(c.path), nil
		}
		return nil, fmt.Errorf("GET %s returned HTTP 429", c.path)
	}}
	w, _ := newTestWalker(t, db, api, garminWalkOptions{days: 200, backfill: true, now: fixedClock("2026-09-08")})
	out := w.walkSeries(context.Background(), seriesNamed(t, "steps"))

	if !out.errored {
		t.Fatal("a 429 must fail the series, not be swallowed as a warning")
	}
	if !errors.Is(out.err, errGarminRateLimited) {
		t.Fatalf("error = %v, want it to wrap errGarminRateLimited", out.err)
	}
	if len(api.calls) != 2 {
		t.Fatalf("made %d calls, want exactly 2: the walk must stop on the first 429 rather than retry or continue", len(api.calls))
	}
	// The window that landed before the 429 is still bookmarked.
	st, _ := db.GetGarminSeriesState("steps")
	if st.LastCompleteDay == "" {
		t.Fatal("the window stored before the 429 was not bookmarked; a rate-limited run must not throw away completed work")
	}
}

func TestIsRateLimited_RecognisesBothErrorShapes(t *testing.T) {
	cases := map[string]bool{
		"GET /x returned HTTP 429":                    true,
		"rate limited: endpoint class read exhausted": true,
		"GET /x returned HTTP 500":                    false,
		"":                                            false,
		"GET /x returned HTTP 4290000 not a real status": true, // substring match is deliberate: over-stopping beats a retry storm
	}
	for msg, want := range cases {
		var err error
		if msg != "" {
			err = errors.New(msg)
		}
		if got := isRateLimited(err); got != want {
			t.Fatalf("isRateLimited(%q) = %v, want %v", msg, got, want)
		}
	}
}

