func TestPacer_SpacesEveryCallButTheFirst(t *testing.T) {
	db := testStore(t)
	api := &fakeGarmin{respond: func(c fakeCall, _ int) (json.RawMessage, error) {
		return stepsWindowPayload(c.path), nil
	}}
	w, rec := newTestWalker(t, db, api, garminWalkOptions{days: 84, delay: 300 * time.Millisecond, now: fixedClock("2026-09-08")})
	w.walkSeries(context.Background(), seriesNamed(t, "steps"))

	if len(api.calls) != 3 {
		t.Fatalf("calls = %d, want 3", len(api.calls))
	}
	if rec.n != 2 {
		t.Fatalf("paused %d times for %d calls, want 2: the first call must not wait", rec.n, len(api.calls))
	}
	if rec.total != 600*time.Millisecond {
		t.Fatalf("total pacing = %s, want 600ms (2 gaps at the 300ms default)", rec.total)
	}
}

